CREATE TABLE academic.programs (
    program_id      SERIAL PRIMARY KEY,
    program_code    VARCHAR(10)  NOT NULL UNIQUE,
    program_name    VARCHAR(150) NOT NULL,
    department      VARCHAR(150) NOT NULL DEFAULT 'Computer Engineering'
);

-- ---------------------------------------------------------------------
-- 2. academic_terms -- semesters / academic years, used to scope fees,
--    enrollments, and staffing assignments
-- ---------------------------------------------------------------------
CREATE TABLE academic.academic_terms (
    term_id         SERIAL PRIMARY KEY,
    academic_year   VARCHAR(9)  NOT NULL,                 -- e.g. '2023/2024'
    semester        SMALLINT    NOT NULL CHECK (semester IN (1, 2, 3)),
    start_date      DATE,
    end_date        DATE,
    UNIQUE (academic_year, semester)
);

-- ---------------------------------------------------------------------
-- 3. students -- Functionality 1: Student Personal Information
-- ---------------------------------------------------------------------
CREATE TABLE academic.students (
    student_id      VARCHAR(15) PRIMARY KEY,               -- university-issued ID
    full_name       VARCHAR(150) NOT NULL,
    gender          VARCHAR(10),
    date_of_birth   DATE,
    email           VARCHAR(150) UNIQUE,
    phone           VARCHAR(20),
    address         TEXT,
    program_id      INT REFERENCES academic.programs(program_id),
    level           SMALLINT CHECK (level IN (100, 200, 300, 400)),
    admission_year  INT,
    status          VARCHAR(20) NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'suspended', 'graduated', 'withdrawn')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_students_program ON academic.students(program_id);
CREATE INDEX idx_students_level   ON academic.students(level);

-- ---------------------------------------------------------------------
-- 4. fee_structure -- how much a program/level owes per term
-- ---------------------------------------------------------------------
CREATE TABLE academic.fee_structure (
    fee_structure_id SERIAL PRIMARY KEY,
    program_id       INT NOT NULL REFERENCES academic.programs(program_id),
    level            SMALLINT NOT NULL CHECK (level IN (100, 200, 300, 400)),
    term_id          INT NOT NULL REFERENCES academic.academic_terms(term_id),
    amount_due       NUMERIC(10, 2) NOT NULL CHECK (amount_due >= 0),
    UNIQUE (program_id, level, term_id)
);

-- ---------------------------------------------------------------------
-- 5. fee_payments -- Functionality 2: Student Fees Payments
-- ---------------------------------------------------------------------
CREATE TABLE academic.fee_payments (
    payment_id      SERIAL PRIMARY KEY,
    student_id      VARCHAR(15) NOT NULL REFERENCES academic.students(student_id) ON DELETE CASCADE,
    term_id         INT NOT NULL REFERENCES academic.academic_terms(term_id),
    amount_paid     NUMERIC(10, 2) NOT NULL CHECK (amount_paid > 0),
    payment_date    DATE NOT NULL DEFAULT CURRENT_DATE,
    payment_method  VARCHAR(20) CHECK (payment_method IN ('mobile_money', 'bank_transfer', 'cash', 'card')),
    reference_no    VARCHAR(50) UNIQUE
);

CREATE INDEX idx_payments_student ON academic.fee_payments(student_id);
CREATE INDEX idx_payments_term    ON academic.fee_payments(term_id);

-- ---------------------------------------------------------------------
-- 6. courses -- courses offered by the department
-- ---------------------------------------------------------------------
CREATE TABLE academic.courses (
    course_code     VARCHAR(15) PRIMARY KEY,
    course_title    VARCHAR(150) NOT NULL,
    credit_hours    SMALLINT NOT NULL CHECK (credit_hours > 0),
    level           SMALLINT CHECK (level IN (100, 200, 300, 400)),
    program_id      INT REFERENCES academic.programs(program_id)
);

-- ---------------------------------------------------------------------
-- 7. course_enrollments -- Functionality 3: Course Enrollment
-- ---------------------------------------------------------------------
CREATE TABLE academic.course_enrollments (
    enrollment_id    SERIAL PRIMARY KEY,
    student_id       VARCHAR(15) NOT NULL REFERENCES academic.students(student_id) ON DELETE CASCADE,
    course_code      VARCHAR(15) NOT NULL REFERENCES academic.courses(course_code) ON DELETE CASCADE,
    term_id          INT NOT NULL REFERENCES academic.academic_terms(term_id),
    enrollment_date  DATE NOT NULL DEFAULT CURRENT_DATE,
    grade            VARCHAR(2),
    UNIQUE (student_id, course_code, term_id)
);

CREATE INDEX idx_enroll_student ON academic.course_enrollments(student_id);
CREATE INDEX idx_enroll_course  ON academic.course_enrollments(course_code);
CREATE INDEX idx_enroll_term    ON academic.course_enrollments(term_id);

-- ---------------------------------------------------------------------
-- 8. lecturers
-- ---------------------------------------------------------------------
CREATE TABLE academic.lecturers (
    lecturer_id     SERIAL PRIMARY KEY,
    full_name       VARCHAR(150) NOT NULL,
    email           VARCHAR(150) UNIQUE,
    phone           VARCHAR(20),
    rank            VARCHAR(50),
    office          VARCHAR(50)
);

-- ---------------------------------------------------------------------
-- 9. teaching_assistants -- students who also serve as TAs
-- ---------------------------------------------------------------------
CREATE TABLE academic.teaching_assistants (
    ta_id           SERIAL PRIMARY KEY,
    student_id      VARCHAR(15) REFERENCES academic.students(student_id),
    full_name       VARCHAR(150) NOT NULL,
    email           VARCHAR(150),
    phone           VARCHAR(20)
);

-- ---------------------------------------------------------------------
-- 10. lecturer_course_assignments -- Functionality 4: Lecturer to Course
-- ---------------------------------------------------------------------
CREATE TABLE academic.lecturer_course_assignments (
    assignment_id   SERIAL PRIMARY KEY,
    lecturer_id     INT NOT NULL REFERENCES academic.lecturers(lecturer_id) ON DELETE CASCADE,
    course_code     VARCHAR(15) NOT NULL REFERENCES academic.courses(course_code) ON DELETE CASCADE,
    term_id         INT NOT NULL REFERENCES academic.academic_terms(term_id),
    role            VARCHAR(30) NOT NULL DEFAULT 'main_lecturer',
    UNIQUE (course_code, term_id, role, lecturer_id)
);

CREATE INDEX idx_lca_lecturer ON academic.lecturer_course_assignments(lecturer_id);
CREATE INDEX idx_lca_course   ON academic.lecturer_course_assignments(course_code);

-- ---------------------------------------------------------------------
-- 11. ta_assignments -- Functionality 5: Lecturer to TA assignment
-- ---------------------------------------------------------------------
CREATE TABLE academic.ta_assignments (
    ta_assignment_id SERIAL PRIMARY KEY,
    ta_id            INT NOT NULL REFERENCES academic.teaching_assistants(ta_id) ON DELETE CASCADE,
    lecturer_id      INT NOT NULL REFERENCES academic.lecturers(lecturer_id) ON DELETE CASCADE,
    course_code      VARCHAR(15) NOT NULL REFERENCES academic.courses(course_code) ON DELETE CASCADE,
    term_id          INT NOT NULL REFERENCES academic.academic_terms(term_id),
    UNIQUE (ta_id, course_code, term_id)
);

CREATE INDEX idx_taa_ta       ON academic.ta_assignments(ta_id);
CREATE INDEX idx_taa_lecturer ON academic.ta_assignments(lecturer_id);

-- ---------------------------------------------------------------------
-- 12. app_users -- backs the Next.js login / register / dashboard
-- ---------------------------------------------------------------------
CREATE TABLE academic.app_users (
    user_id         SERIAL PRIMARY KEY,
    email           VARCHAR(150) NOT NULL UNIQUE,
    password_hash   TEXT NOT NULL,                          -- bcrypt hash, never plaintext
    role            VARCHAR(20) NOT NULL DEFAULT 'student'
                        CHECK (role IN ('admin', 'lecturer', 'student')),
    student_id      VARCHAR(15) REFERENCES academic.students(student_id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
