-- =====================================================================
-- 12_function_outstanding_fees.sql
-- Function: academic.get_outstanding_fees()
--
-- Purpose: For every student, calculate how much they still owe by
--          comparing what is billed to them (academic.fee_structure,
--          keyed on the student's program + level) per term against
--          what they have actually paid (academic.fee_payments) for
--          that same term. Returns the result as a single JSON array,
--          one object per student, with a per-term breakdown plus a
--          grand total outstanding balance.
--
-- Run this WHILE CONNECTED to ceng_dept_db:
--   psql -U postgres -d ceng_dept_db -f 12_function_outstanding_fees.sql
-- =====================================================================

SET search_path TO academic, public;

CREATE OR REPLACE FUNCTION academic.get_outstanding_fees(
    p_student_id VARCHAR DEFAULT NULL
)
RETURNS JSON
LANGUAGE sql
STABLE
AS $$
    WITH billed AS (
        -- What each student is billed for, term by term, based on
        -- their program + level at the time.
        SELECT
            s.student_id,
            s.full_name,
            fs.term_id,
            t.academic_year,
            t.semester,
            fs.amount_due
        FROM academic.students s
        JOIN academic.fee_structure fs
            ON fs.program_id = s.program_id
           AND fs.level      = s.level
        JOIN academic.academic_terms t
            ON t.term_id = fs.term_id
    ),
    paid AS (
        -- What each student has actually paid, term by term
        -- (a student may pay in several installments per term).
        SELECT
            student_id,
            term_id,
            SUM(amount_paid) AS amount_paid
        FROM academic.fee_payments
        GROUP BY student_id, term_id
    ),
    per_term AS (
        SELECT
            b.student_id,
            b.full_name,
            b.term_id,
            b.academic_year,
            b.semester,
            b.amount_due,
            COALESCE(p.amount_paid, 0)                         AS amount_paid,
            GREATEST(b.amount_due - COALESCE(p.amount_paid, 0), 0) AS outstanding
        FROM billed b
        LEFT JOIN paid p
            ON p.student_id = b.student_id
           AND p.term_id    = b.term_id
    ),
    per_student AS (
        SELECT
            student_id,
            full_name,
            SUM(amount_due)   AS total_billed,
            SUM(amount_paid)  AS total_paid,
            SUM(outstanding)  AS total_outstanding,
            JSON_AGG(
                JSON_BUILD_OBJECT(
                    'academic_year', academic_year,
                    'semester',      semester,
                    'amount_due',    amount_due,
                    'amount_paid',   amount_paid,
                    'outstanding',   outstanding
                )
                ORDER BY academic_year, semester
            ) AS term_breakdown
        FROM per_term
        WHERE p_student_id IS NULL OR student_id = p_student_id
        GROUP BY student_id, full_name
    )
    SELECT COALESCE(JSON_AGG(
        JSON_BUILD_OBJECT(
            'student_id',         student_id,
            'full_name',          full_name,
            'total_billed',       total_billed,
            'total_paid',         total_paid,
            'total_outstanding',  total_outstanding,
            'terms',              term_breakdown
        )
        ORDER BY student_id
    ), '[]'::json)
    FROM per_student;
$$;

COMMENT ON FUNCTION academic.get_outstanding_fees(VARCHAR) IS
  'Returns a JSON array of outstanding fee balances per student, with a per-term breakdown. Pass a student_id to filter to one student, or omit/NULL for all students.';

